import { useCallback, useEffect, useState } from 'react';
import Head from 'next/head';
import { adminFetch, adminMutation, apiErrorMessage } from '@/lib/admin-client';

type Queue = { name: string; waiting?: number; active?: number; completed?: number; failed?: number; delayed?: number; paused?: number };
type QueueResponse = { queues: Queue[] }; type Job = { id: string; name: string; attempts: number; failedReason?: string; data_preview: string; timestamp?: number };
type Translation = { key: string; base_ar?: string; current_ar?: string; current_en?: string; current_ur?: string; overridden?: boolean }; type Translations = { total_keys: number; overridden_count: number; data: Translation[] };
type Seo = { data: Array<{ route_key: string; indexable: boolean; reason?: string; updatedAt?: string }> }; type Flags = { data: Array<{ key: string; enabled: boolean; rollout_percentage: number; updatedAt?: string | null; source?: string }>; stores: { canonical: number; legacy: number } };

export default function SystemOpsPage() {
  const [queues, setQueues] = useState<Queue[]>([]); const [jobs, setJobs] = useState<Job[]>([]); const [translations, setTranslations] = useState<Translations>({ total_keys: 0, overridden_count: 0, data: [] }); const [seo, setSeo] = useState<Seo>({ data: [] }); const [flags, setFlags] = useState<Flags>({ data: [], stores: { canonical: 0, legacy: 0 } }); const [tab, setTab] = useState<'queues' | 'translations' | 'seo' | 'flags'>('queues'); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [lang, setLang] = useState('ar'); const [translationKey, setTranslationKey] = useState(''); const [translationValue, setTranslationValue] = useState(''); const [flag, setFlag] = useState({ key: '', enabled: true, rollout_percentage: '100', reason: '' });
  const load = useCallback(async () => { setLoading(true); setError(''); try { const [q, t, s, f] = await Promise.all([adminFetch<QueueResponse>('/ops/queues'), adminFetch<Translations>(`/ops/translations?lang=${lang}`), adminFetch<Seo>('/ops/seo/controls'), adminFetch<Flags>('/governance-controls/feature-flags')]); setQueues(q.queues || []); setTranslations(t); setSeo(s); setFlags(f); if (q.queues[0]) { const j = await adminFetch<{ data: Job[] }>(`/ops/queues/${encodeURIComponent(q.queues[0].name)}/jobs?state=failed&start=0&end=49`); setJobs(j.data || []); } } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تحميل حالة التشغيل.')); } finally { setLoading(false); } }, [lang]);
  useEffect(() => { void load(); }, [load]);
  async function retryAll(queue: Queue) { const reason = window.prompt('سبب إعادة محاولة كل المهام الفاشلة (5 أحرف على الأقل):'); if (!reason || reason.trim().length < 5 || !window.confirm('سيعيد backend محاولة المهام الفاشلة فعلياً. متابعة؟')) return; setSaving(true); try { await adminMutation(`/ops/queues/${encodeURIComponent(queue.name)}/retry-failed`, 'POST', { reason: reason.trim(), limit: 100 }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إعادة المحاولة.')); } finally { setSaving(false); } }
  async function retryOne(queue: Queue, job: Job) { const reason = window.prompt('سبب إعادة محاولة المهمة:'); if (!reason || reason.trim().length < 5) return; setSaving(true); try { await adminMutation(`/ops/queues/${encodeURIComponent(queue.name)}/jobs/${encodeURIComponent(job.id)}/retry`, 'POST', { reason: reason.trim() }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر إعادة محاولة المهمة.')); } finally { setSaving(false); } }
  async function saveTranslation(event: React.FormEvent) { event.preventDefault(); if (!translationKey || !translationValue) return; setSaving(true); try { await adminMutation('/ops/translations', 'POST', { key: translationKey, lang, value: translationValue, reason: 'تحديث ترجمة من وحدة التشغيل' }); setTranslationKey(''); setTranslationValue(''); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حفظ الترجمة.')); } finally { setSaving(false); } }
  async function saveSeo(route: string, indexable: boolean) { const reason = window.prompt(`سبب ${indexable ? 'إتاحة' : 'حجب'} الفهرسة للمسار:`); if (!reason || reason.trim().length < 5) return; setSaving(true); try { await adminMutation('/ops/seo/controls', 'POST', { route_key: route, indexable, reason: reason.trim() }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر تغيير تحكم SEO.')); } finally { setSaving(false); } }
  async function saveFlag(event: React.FormEvent) { event.preventDefault(); if (flag.reason.trim().length < 5) { setError('سبب تعديل الراية مطلوب.'); return; } setSaving(true); try { await adminMutation('/governance-controls/feature-flags', 'POST', { key: flag.key, enabled: flag.enabled, rollout_percentage: Number(flag.rollout_percentage), reason: flag.reason.trim() }); setFlag({ key: '', enabled: true, rollout_percentage: '100', reason: '' }); await load(); } catch (cause) { setError(apiErrorMessage(cause, 'تعذر حفظ الراية.')); } finally { setSaving(false); } }
  return <><Head><title>تشغيل النظام | نبض</title></Head><section dir="rtl" className="space-y-6 p-6 md:p-8"><header><h1 className="text-3xl font-bold">تشغيل النظام</h1><p className="mt-1 text-sm text-slate-500">مراقبة خادمية للطوابير والترجمات وSEO والرايات مع إجراءات مدققة.</p></header><div className="flex flex-wrap gap-2">{(['queues', 'translations', 'seo', 'flags'] as const).map((item) => <button key={item} onClick={() => setTab(item)} className={`rounded-lg px-4 py-2 text-sm font-bold ${tab === item ? 'bg-teal-700 text-white' : 'border bg-white'}`}>{item === 'queues' ? 'الطوابير' : item === 'translations' ? 'الترجمات' : item === 'seo' ? 'SEO' : 'Feature Flags'}</button>)}</div>{error ? <p role="alert" className="rounded-lg bg-rose-50 p-3 text-rose-700">{error}</p> : null}{loading ? <p className="rounded-2xl border bg-white p-10 text-center text-slate-500">جارٍ تحميل حالة النظام…</p> : null}{!loading && tab === 'queues' ? <div className="space-y-5"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">عمق الطوابير</h2><div className="mt-4 grid gap-3 md:grid-cols-3">{queues.map((queue) => <div key={queue.name} className="rounded-xl border p-4"><strong>{queue.name}</strong><dl className="mt-3 grid grid-cols-2 gap-2 text-sm"><dt>waiting</dt><dd>{queue.waiting ?? 0}</dd><dt>active</dt><dd>{queue.active ?? 0}</dd><dt>failed</dt><dd className="font-bold text-rose-700">{queue.failed ?? 0}</dd><dt>delayed</dt><dd>{queue.delayed ?? 0}</dd></dl><button disabled={saving} onClick={() => void retryAll(queue)} className="mt-4 rounded bg-teal-700 px-3 py-2 text-sm font-bold text-white">إعادة المحاولات الفاشلة</button></div>)}</div></article><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">المهام الفاشلة</h2><div className="mt-4 overflow-x-auto"><table className="min-w-full text-right text-sm"><thead><tr className="border-b text-slate-500"><th className="p-2">المعرف</th><th className="p-2">المهمة</th><th className="p-2">المحاولات</th><th className="p-2">السبب</th><th className="p-2">إجراء</th></tr></thead><tbody>{jobs.length ? jobs.map((job) => <tr key={job.id} className="border-b"><td className="p-2 font-mono text-xs">{job.id}</td><td className="p-2">{job.name}</td><td className="p-2">{job.attempts}</td><td className="max-w-sm truncate p-2 text-xs">{job.failedReason || '—'}</td><td className="p-2">{queues[0] ? <button disabled={saving} onClick={() => void retryOne(queues[0], job)} className="rounded border px-2 py-1 text-xs">إعادة المحاولة</button> : null}</td></tr>) : <tr><td colSpan={5} className="p-6 text-center text-slate-500">لا توجد مهام فاشلة حالياً.</td></tr>}</tbody></table></div></article></div> : null}{!loading && tab === 'translations' ? <div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><div className="flex items-center justify-between"><h2 className="text-xl font-bold">قاموس الترجمات</h2><select value={lang} onChange={(e) => setLang(e.target.value)} className="rounded border p-2 text-sm"><option value="ar">العربية</option><option value="en">English</option><option value="ur">Urdu</option></select></div><p className="mt-2 text-sm text-slate-500">{translations.total_keys} مفتاح، {translations.overridden_count} override محفوظ.</p><div className="mt-4 max-h-96 overflow-auto"><table className="min-w-full text-right text-xs"><thead><tr className="border-b"><th className="p-2">المفتاح</th><th className="p-2">العربي</th><th className="p-2">القيمة الحالية</th></tr></thead><tbody>{translations.data.map((row) => <tr key={row.key} className="border-b"><td className="p-2 font-mono">{row.key}</td><td className="p-2">{row.base_ar || '—'}</td><td className="p-2">{lang === 'ar' ? row.current_ar : lang === 'en' ? row.current_en : row.current_ur}</td></tr>)}</tbody></table></div></article><form onSubmit={saveTranslation} className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">تعديل ترجمة</h2><input required value={translationKey} onChange={(e) => setTranslationKey(e.target.value)} className="mt-4 w-full rounded border p-2 font-mono text-sm" placeholder="المفتاح"/><textarea required value={translationValue} onChange={(e) => setTranslationValue(e.target.value)} className="mt-3 min-h-28 w-full rounded border p-2" placeholder="القيمة الجديدة"/><button disabled={saving} className="mt-3 rounded bg-teal-700 px-4 py-2 font-bold text-white">حفظ الترجمة</button></form></div> : null}{!loading && tab === 'seo' ? <article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">تحكم النشر والفهرسة</h2><p className="mt-1 text-sm text-slate-500">تطبيق indexable ينعكس على sitemap وrobots في طبقة النشر الخادمية.</p><div className="mt-4 overflow-x-auto"><table className="min-w-full text-right text-sm"><thead><tr className="border-b text-slate-500"><th className="p-2">المسار</th><th className="p-2">الفهرسة</th><th className="p-2">السبب</th><th className="p-2">إجراء</th></tr></thead><tbody>{seo.data.map((row) => <tr key={row.route_key} className="border-b"><td className="p-2">{row.route_key}</td><td className="p-2">{row.indexable ? 'متاح' : 'محجوب'}</td><td className="p-2">{row.reason || '—'}</td><td className="p-2"><button disabled={saving} onClick={() => void saveSeo(row.route_key, !row.indexable)} className="rounded border px-2 py-1 text-xs">{row.indexable ? 'حجب' : 'إتاحة'}</button></td></tr>)}</tbody></table></div></article> : null}{!loading && tab === 'flags' ? <div className="grid gap-6 lg:grid-cols-2"><article className="rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">الرايات الموحدة</h2><p className="mt-1 text-sm text-slate-500">المخازن: canonical {flags.stores.canonical} · legacy {flags.stores.legacy}</p><ul className="mt-4 divide-y">{flags.data.map((row) => <li key={row.key} className="flex items-center justify-between py-3"><div><strong dir="ltr">{row.key}</strong><p className="mt-1 text-xs text-slate-500">{row.enabled ? 'مفعلة' : 'معطلة'} · rollout {row.rollout_percentage}%</p></div></li>)}</ul></article><form onSubmit={saveFlag} className="space-y-3 rounded-2xl border bg-white p-6 shadow-sm"><h2 className="text-xl font-bold">تعديل راية</h2><input required value={flag.key} onChange={(e) => setFlag({ ...flag, key: e.target.value })} dir="ltr" className="w-full rounded border p-2" placeholder="feature.key"/><label className="flex gap-2 text-sm"><input type="checkbox" checked={flag.enabled} onChange={(e) => setFlag({ ...flag, enabled: e.target.checked })}/> مفعلة</label><label className="block text-sm">نسبة rollout<input required value={flag.rollout_percentage} onChange={(e) => setFlag({ ...flag, rollout_percentage: e.target.value })} type="number" min="0" max="100" className="mt-1 w-full rounded border p-2"/></label><textarea required minLength={5} value={flag.reason} onChange={(e) => setFlag({ ...flag, reason: e.target.value })} className="min-h-20 w-full rounded border p-2" placeholder="سبب التغيير"/><button disabled={saving} className="rounded bg-teal-700 px-4 py-2 font-bold text-white">حفظ وتدقيق</button></form></div> : null}</section></>;
}
